class SendMessageDialogController{constructor($mdDialog,DispatchData,toastrService,selectedCourierId){this.$mdDialog=$mdDialog;this.DispatchData=DispatchData;this.toastrService=toastrService;this._selectedCourierId=selectedCourierId;this.message=""}async submit(message){try{console.log("Message",message);console.log("Courier",this._selectedCourierId);await this.DispatchData.sendSMS(this._selectedCourierId,ContactID,FirstName,message);this.toastrService.showSuccessToast("Message Sent!")}catch(error){this.toastrService.showErrorToast(error.message)}finally{this.$mdDialog.hide()}}cancel(){this.$mdDialog.cancel()}}